package be.winnetrie.mod.simpleserverutilities.network;
import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;
public record KitDataPayload(boolean admin,String selectedId,String json,String notice,boolean error,long requestId) implements CustomPacketPayload{public static final Type<KitDataPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(SimpleServerUtilities.MODID,"kit_data"));public static final StreamCodec<RegistryFriendlyByteBuf,KitDataPayload> STREAM_CODEC=StreamCodec.of(KitDataPayload::encode,KitDataPayload::decode);public KitDataPayload{selectedId=PayloadBounds.string(selectedId,64);json=PayloadBounds.string(json,65535);notice=PayloadBounds.string(notice,1024);requestId=Math.max(0L,requestId);}private static void encode(RegistryFriendlyByteBuf b,KitDataPayload p){b.writeBoolean(p.admin);b.writeUtf(p.selectedId,64);b.writeUtf(p.json,65535);b.writeUtf(p.notice,1024);b.writeBoolean(p.error);b.writeVarLong(p.requestId);}private static KitDataPayload decode(RegistryFriendlyByteBuf b){return new KitDataPayload(b.readBoolean(),b.readUtf(64),b.readUtf(65535),b.readUtf(1024),b.readBoolean(),b.readVarLong());}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
